import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import fm from 'front-matter';

interface PostData {
  slug: string;
  frontmatter: {
    title: string;
    date: string;
  };
}

const Blog: React.FC = () => {
  const [posts, setPosts] = useState<PostData[]>([]);

  useEffect(() => {
    const fetchPosts = async () => {
      const postFiles = [
        '/posts/2024-06-11-NLP-to-Transformers.md',
        '/posts/2024-06-18-Calc-III-study-guide.md'
        // Add more posts here
      ];

      const posts = await Promise.all(
        postFiles.map(async (file) => {
          const response = await fetch(file);
          const text = await response.text();
          const { attributes: frontmatter } = fm<{ title: string; date: string }>(text);
          const slug = file.split('/').pop()?.replace('.md', '') || '';

          debugger; // This will pause execution and allow you to inspect `frontmatter` and `slug`

          return { slug, frontmatter };
        })
      );

      posts.sort((a, b) => new Date(b.frontmatter.date).getTime() - new Date(a.frontmatter.date).getTime());
      setPosts(posts);
    };

    fetchPosts();
  }, []);

  return (
    <div className="min-h-screen bg-gray-100 p-5">
      <div className="container mx-auto">
        <h1 className="text-4xl font-bold text-center text-customPurple mb-10">Blog</h1>
        <div className="grid lg:grid-cols-3 md:grid-cols-2 gap-6">
          <ul>
            {posts.map((post) => (
              <li key={post.slug}>
                <Link to={`/posts/${post.slug}`}>
                  <h2 className="text-2xl mt-12">{post.frontmatter.title}</h2>
                  <p>{new Date(post.frontmatter.date).toDateString()}</p>
                </Link>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default Blog;
